import { useCallback, useEffect, useRef, useState } from 'react'
import { GLAZES, PRODUCTS, MAKING, CARE, NOTES, SHIPPING, glazeName, glaze } from './data.js'
import { CREDITS } from './credits.js'
import TrueScale from './TrueScale.jsx'
import Firing from './Firing.jsx'

const RATIO = {
  'mug-tall': '4 / 5', 'mug-low': '1 / 1', 'cup-espresso': '1 / 1',
  'bowl-deep': '1 / 1', 'bowl-shallow': '3 / 2', 'plate-side': '1 / 1',
  'plate-dinner': '3 / 2', jug: '4 / 5', vase: '4 / 5',
}
const SPAN = {
  'mug-tall': 2, 'mug-low': 2, 'cup-espresso': 2,
  'bowl-deep': 3, 'bowl-shallow': 3,
  'plate-side': 2, 'plate-dinner': 2, jug: 2, vase: 2,
}

/* ------------------------------------------------------------------ marks */
// Notation, drawn: the care facts as marks you can read at a glance, the way
// they are stamped into the underside of a piece.
function Mark({ kind, ok }) {
  const label = kind === 'dishwasher'
    ? (ok ? 'Dishwasher safe' : 'Not dishwasher safe')
    : (ok ? 'Microwave safe' : 'Not microwave safe')
  return (
    <span className={'mark' + (ok ? '' : ' mark--no')} title={label}>
      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
        {kind === 'dishwasher' ? (
          <>
            <rect x="3.5" y="3.5" width="17" height="17" rx="1.5" />
            <path d="M7 8.4h10" />
            <path d="M9.2 12.6c1 0 1 1.5 2 1.5s1-1.5 2-1.5 1 1.5 2 1.5" />
            <path d="M9.2 16c1 0 1 1.5 2 1.5s1-1.5 2-1.5 1 1.5 2 1.5" />
          </>
        ) : (
          <>
            <rect x="2.5" y="5.5" width="19" height="13" rx="1.5" />
            <path d="M15 5.5v13" />
            <path d="M5.4 12.2c.9-1.6 2-1.6 2.9 0s2 1.6 2.9 0" />
          </>
        )}
        {!ok && <path className="mark__bar" d="M4 20L20 4" />}
      </svg>
      <span className="sr">{label}</span>
    </span>
  )
}

/* ------------------------------------------------------------------- card */
function Card({ p, active, selected, onAdd, onSelect }) {
  const imgRef = useRef(null)
  const offered = p.glazes.includes(active.id)
  const out = p.stock === 'out'
  return (
    <article
      id={'piece-' + p.id}
      className={
        'card' +
        (out ? ' is-out' : '') +
        (offered ? '' : ' is-elsewhere') +
        (selected ? ' is-selected' : '')
      }
      style={{ '--span': SPAN[p.id] }}
      onMouseEnter={() => onSelect(p.id)}
    >
      <div className="card__figure" style={{ aspectRatio: RATIO[p.id] }}>
        <img ref={imgRef} src={p.img} alt={p.name + ', thrown stoneware.'} loading="lazy" />
        {out && <span className="card__flag mono">Sold out</span>}
      </div>

      <div className="card__body">
        <h3 className="card__name">
          {p.name}
          <span className="card__price mono">£{p.price}</span>
        </h3>

        <dl className="card__specs mono">
          <div><dt>Size</dt><dd>{p.dims}</dd></div>
          {p.capacity && <div><dt>Holds</dt><dd>{p.capacity}</dd></div>}
          <div className="card__care">
            <dt className="sr">Care</dt>
            <dd><Mark kind="dishwasher" ok={p.dishwasher} /><Mark kind="microwave" ok={p.microwave} /></dd>
          </div>
        </dl>

        {out ? (
          <p className="card__outnote">
            Sold out. The next one is about six weeks away &mdash; one full cycle
            of throwing, drying, and two firings.
          </p>
        ) : null}

        <div className="card__buy">
          <span className="mono card__buylabel">
            {offered ? 'Add in' : 'Not made in ' + active.name + ' — add in'}
          </span>
          <div className="card__glazes">
            {p.glazes.map((gid) => (
              <button
                key={gid}
                type="button"
                className={'gbtn' + (gid === active.id ? ' is-current' : '')}
                disabled={out}
                onClick={() => onAdd(p, gid, imgRef.current)}
              >
                <span className="gbtn__swatch" style={{ background: glaze(gid).accent }} aria-hidden="true" />
                {glazeName(gid)}
                <span className="sr">
                  {out ? ' — sold out' : ' — add ' + p.name + ' in ' + glazeName(gid) + ' to the bag'}
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </article>
  )
}

/* -------------------------------------------------------------- the route */
export default function App() {
  const [bag, setBag] = useState([])
  const [active, setActive] = useState('ash')
  const [paint, setPaint] = useState('ash')
  const [wash, setWash] = useState(null)
  const [open, setOpen] = useState(false)
  const [selected, setSelected] = useState(null)
  const bagBtn = useRef(null)
  const timers = useRef([])

  useEffect(() => () => timers.current.forEach(clearTimeout), [])

  const reduced = () =>
    typeof window !== 'undefined' &&
    window.matchMedia &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches

  // The glaze runs down the page rather than switching. One band of the new
  // ground, soft at both edges, travelling the viewport; the page commits its
  // colours underneath it as it passes.
  const chooseGlaze = useCallback((id) => {
    setActive((cur) => {
      if (cur === id) return cur
      if (reduced()) {
        setPaint(id)
        return id
      }
      setWash({ id, key: Date.now() })
      timers.current.push(setTimeout(() => setPaint(id), 340))
      timers.current.push(setTimeout(() => setWash(null), 980))
      return id
    })
  }, [])

  const add = useCallback((p, gid, imgEl) => {
    if (p.stock === 'out') return
    setBag((lines) => {
      const at = lines.findIndex((l) => l.id === p.id && l.glaze === gid)
      if (at === -1) {
        return [...lines, { id: p.id, name: p.name, glaze: gid, price: p.price, qty: 1 }]
      }
      const next = lines.slice()
      next[at] = { ...next[at], qty: next[at].qty + 1 }
      return next
    })
    // the piece you chose travels to the bag, so the bag is never a surprise
    if (imgEl && bagBtn.current && !reduced() && typeof imgEl.animate === 'function') {
      const a = imgEl.getBoundingClientRect()
      const b = bagBtn.current.getBoundingClientRect()
      const fly = imgEl.cloneNode()
      Object.assign(fly.style, {
        position: 'fixed',
        left: a.left + 'px',
        top: a.top + 'px',
        width: a.width + 'px',
        height: a.height + 'px',
        objectFit: 'cover',
        zIndex: 90,
        pointerEvents: 'none',
        borderRadius: '2px',
      })
      document.body.appendChild(fly)
      const s = Math.max(0.1, 44 / Math.max(a.width, a.height))
      const dx = b.left + b.width / 2 - a.left - a.width / 2
      const dy = b.top + b.height / 2 - a.top - a.height / 2
      fly.animate(
        [
          { transform: 'translate(0,0) scale(1)', opacity: 1 },
          { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(' + s + ')', opacity: 0.12 },
        ],
        { duration: 620, easing: 'cubic-bezier(.4,.1,.2,1)' },
      ).onfinish = () => fly.remove()
    }
  }, [])

  const remove = useCallback((i) => setBag((l) => l.filter((_, x) => x !== i)), [])
  const bump = useCallback((i, d) => setBag((l) => {
    const n = l.slice()
    const q = n[i].qty + d
    if (q < 1) return l.filter((_, x) => x !== i)
    n[i] = { ...n[i], qty: q }
    return n
  }), [])

  const total = bag.reduce((s, l) => s + l.price * l.qty, 0)
  const count = bag.reduce((s, l) => s + l.qty, 0)
  const g = glaze(paint)
  const activeG = glaze(active)
  const madeIn = PRODUCTS.filter((p) => p.glazes.includes(active)).length

  const jumpTo = useCallback((id) => {
    setSelected(id)
    const el = document.getElementById('piece-' + id)
    if (el) el.scrollIntoView({ behavior: reduced() ? 'auto' : 'smooth', block: 'center' })
  }, [])

  return (
    <div
      className="route"
      style={{
        '--paper': g.paper,
        '--paper-deep': g.paperDeep,
        '--ink': g.ink,
        '--accent': g.accent,
        '--rule': g.rule,
      }}
    >
      {wash && (
        <div key={wash.key} className="wash" aria-hidden="true" style={{ '--to': glaze(wash.id).paper }} />
      )}

      {/* ------------------------------------------------------- masthead */}
      <header className="mast">
        <div className="mast__in">
          <a className="mast__logo" href="#top">
            Kilnwork
            <span className="mast__sub mono">Two people, nine pieces</span>
          </a>

          <nav className="mast__nav mono" aria-label="Sections">
            <a href="#difference">The difference</a>
            <a href="#glazes">Glazes</a>
            <a href="#scale">Scale</a>
            <a href="#shop">The nine</a>
            <a href="#firing">The firing</a>
          </nav>

          <fieldset className="picker">
            <legend className="sr">Choose a glaze to see the shop in</legend>
            {GLAZES.map((gl) => (
              <button
                key={gl.id}
                type="button"
                className={'picker__b' + (gl.id === active ? ' is-on' : '')}
                aria-pressed={gl.id === active}
                onClick={() => chooseGlaze(gl.id)}
              >
                <span className="picker__dot" style={{ background: gl.accent }} aria-hidden="true" />
                {gl.name}
              </button>
            ))}
          </fieldset>

          <button
            ref={bagBtn}
            type="button"
            className={'mast__bag' + (count ? ' has-items' : '')}
            onClick={() => setOpen((o) => !o)}
            aria-expanded={open}
            aria-controls="bag-panel"
          >
            Bag <span className="mono">{count}</span>
          </button>
        </div>
      </header>

      {/* ----------------------------------------------------------- hero */}
      <section className="hero" id="top">
        <div className="hero__type">
          <p className="mono hero__kicker">Kilnwork &mdash; a two-person ceramics studio</p>
          <h1 className="hero__h1">
            Nine pieces,<br />thrown and fired here,<br /><em>sold direct.</em>
          </h1>
          <p className="hero__lede">
            The mug in the supermarket costs about a tenth of this one, and it is
            identical to its photograph. This one will not be. That is the whole
            of the difference, and the rest of this page is us showing it to you
            rather than telling you about it.
          </p>
          <div className="hero__acts">
            <a className="btn" href="#shop">See the nine</a>
            <a className="btn btn--quiet" href="#difference">What you are paying for</a>
          </div>
        </div>
        <figure className="hero__fig">
          <img src="/img/hero.webp" alt="A potter's hands raising the wall of a jug on the wheel." />
          <figcaption className="mono">Raising a wall. Every piece on this page starts here.</figcaption>
        </figure>
      </section>

      {/* ----------------------------------------------------- difference */}
      <section className="diff" id="difference" aria-labelledby="diff-h">
        <figure className="diff__fig">
          <img src="/img/foot.webp" alt="The underside of a glazed cup, showing the bare clay foot ring and a mark cut into it." />
          <span className="diff__note diff__note--a">
            <b className="mono">1</b>
            <span>The foot, left bare. Glaze would fuse the piece to the kiln shelf, so it stops short of the bottom.</span>
          </span>
          <span className="diff__note diff__note--b">
            <b className="mono">2</b>
            <span>A mark cut into the clay while it was still soft, before either firing.</span>
          </span>
          <span className="diff__note diff__note--c">
            <b className="mono">3</b>
            <span>Where the glaze ran and stopped. It stops somewhere different on every piece.</span>
          </span>
        </figure>
        <div className="diff__body">
          <h2 className="h2" id="diff-h">Turn it over</h2>
          <p className="lede">
            The underside is where the two mugs stop being comparable. A factory
            mug has a smooth glazed base and a printed code. This has bare clay,
            a mark, and an edge where somebody stopped pouring.
          </p>
          <p>
            None of it is decoration and none of it is optional. It is what the
            making leaves behind, and it is the reason each piece here needs
            reading before you buy it &mdash; so the rest of this page is the
            reading.
          </p>
        </div>
      </section>

      {/* --------------------------------------------------------- glazes */}
      <section className="glazes" id="glazes" aria-labelledby="glazes-h">
        <div className="wrap glazes__head">
          <h2 className="h2" id="glazes-h">Three glazes</h2>
          <p className="lede">
            Pick one and the whole shop below is shown in it. Not every form is
            offered in every glaze, and the page will say so where it is not.
          </p>
        </div>

        <div className="glazes__row">
          {GLAZES.map((gl) => {
            const on = gl.id === active
            return (
              <button
                key={gl.id}
                type="button"
                className={'glazec' + (on ? ' is-on' : '')}
                aria-pressed={on}
                onClick={() => chooseGlaze(gl.id)}
              >
                <span className="glazec__fig">
                  <img src={gl.img} alt={'A piece in the ' + gl.name + ' glaze.'} loading="lazy" />
                </span>
                <span className="glazec__meta">
                  <span className="glazec__name">{gl.name}</span>
                  <span className="glazec__note">{gl.note}</span>
                  <span className="mono glazec__cta">
                    {on ? 'Showing the shop in this' : 'Show the shop in this'}
                  </span>
                </span>
              </button>
            )
          })}
        </div>

        <div className="tiles">
          <figure className="tiles__fig">
            <img src="/img/tiles-a.webp" alt="A board of glaze test tiles, each labelled by hand with its recipe." loading="lazy" />
          </figure>
          <div className="tiles__body">
            <p className="tiles__big">The same recipe, over and over, and never once the same.</p>
            <p>{MAKING[2]}</p>
          </div>
          <figure className="tiles__fig tiles__fig--b">
            <img src="/img/tiles-b.webp" alt="A second board of test tiles from the ash glaze trials." loading="lazy" />
          </figure>
        </div>
      </section>

      <TrueScale selected={selected} onSelect={jumpTo} />

      {/* ----------------------------------------------------------- shop */}
      <section className="shop" id="shop" aria-labelledby="shop-h">
        <div className="wrap shop__head">
          <h2 className="h2" id="shop-h">The nine</h2>
          <p className="mono shop__state">
            Shown in <b>{activeG.name}</b> &mdash; {madeIn} of nine are made in it.
          </p>
        </div>
        <div className="grid">
          {PRODUCTS.map((p) => (
            <Card key={p.id} p={p} active={activeG} selected={selected === p.id} onAdd={add} onSelect={setSelected} />
          ))}
          <aside className="grid__aside">
            <p className="grid__asidebig">Two of the nine are sold out.</p>
            <p>
              We do not take back-orders and we do not make more of something
              because it sold. The Shallow Bowl and the Bottle Vase go back on
              the page when the next firing comes out of the kiln.
            </p>
            <p className="mono grid__asidefoot">About six weeks, give or take a firing.</p>
          </aside>
        </div>
      </section>

      {/* -------------------------------------------------- band + firing */}
      <div className="band">
        <img src="/img/kiln-glow.webp" alt="" aria-hidden="true" loading="lazy" />
        <p className="mono band__cap">Three spy holes in a wood kiln at temperature.</p>
      </div>

      <Firing />

      {/* --------------------------------------------------------- studio */}
      <section className="studio" aria-labelledby="studio-h">
        <figure className="studio__tall">
          <img src="/img/shelves.webp" alt="Freshly thrown cylinders drying on studio boards." loading="lazy" />
          <figcaption className="mono">Thrown, and now waiting. This is most of the six weeks.</figcaption>
        </figure>
        <div className="studio__body">
          <h2 className="h2" id="studio-h">Between firings</h2>
          <p className="lede">
            Almost none of the six weeks is spent making. It is spent waiting for
            water to leave clay slowly enough that nothing cracks, and then
            waiting again for a kiln that is full enough to be worth lighting.
          </p>
        </div>
        <figure className="studio__wide">
          <img src="/img/hands.webp" alt="A potter cupping a finished bowl in both hands." loading="lazy" />
          <figcaption className="mono">Out of the kiln, checked, and either shipped or broken up.</figcaption>
        </figure>
      </section>

      {/* ---------------------------------------------------------- notes */}
      <section className="notes" aria-labelledby="notes-h">
        <div className="wrap">
          <h2 className="h2" id="notes-h">Two notes</h2>
          <div className="notes__row">
            {NOTES.map((n) => (
              <figure key={n.name} className="note">
                <blockquote><p>{n.quote}</p></blockquote>
                <figcaption>
                  <span className="note__name">{n.name}</span>
                  <button type="button" className="note__bought mono" onClick={() => jumpTo(n.piece)}>
                    {n.bought}
                  </button>
                </figcaption>
              </figure>
            ))}
          </div>
        </div>
      </section>

      {/* ------------------------------------------------ care + shipping */}
      <section className="terms" aria-labelledby="terms-h">
        <div className="wrap terms__in">
          <div className="terms__col">
            <h2 className="h2" id="terms-h">Living with it</h2>
            <ul className="terms__list">
              {CARE.map((line, i) => <li key={i}>{line}</li>)}
            </ul>
          </div>
          <div className="terms__col">
            <h2 className="h2">Getting it to you</h2>
            <ul className="terms__list">
              {SHIPPING.map((line, i) => <li key={i}>{line}</li>)}
            </ul>
          </div>
        </div>
      </section>

      {/* --------------------------------------------------------- footer */}
      <footer className="foot">
        <div className="wrap foot__in">
          <div className="foot__brand">
            <p className="foot__mark">Kilnwork</p>
            <p>{MAKING[0]}</p>
          </div>
          <details className="foot__credits">
            <summary className="mono">Photography &mdash; {CREDITS.length} sourced images, credited</summary>
            <ul>
              {CREDITS.map((c) => (
                <li key={c.slot} className="mono">
                  <span className="foot__slot">{c.slot}</span>
                  <a href={c.url} target="_blank" rel="noreferrer noopener">{c.title || 'source'}</a>
                  <span> &mdash; {c.author}, {c.licence}</span>
                </li>
              ))}
            </ul>
          </details>
        </div>
      </footer>

      {/* ------------------------------------------------------------ bag */}
      <div className={'bag' + (open ? ' is-open' : '') + (count ? ' has-items' : '')}>
        <button
          type="button"
          className="bag__handle"
          onClick={() => setOpen((o) => !o)}
          aria-expanded={open}
          aria-controls="bag-panel"
        >
          <span className="bag__handletitle">Bag</span>
          <span className="mono bag__handlesum">
            {count === 0 ? 'empty' : count + (count === 1 ? ' piece · £' : ' pieces · £') + total}
          </span>
          <span className="bag__chev" aria-hidden="true" />
        </button>

        <div className="bag__panel" id="bag-panel" hidden={!open}>
          {bag.length === 0 && <p className="bag__empty">Nothing in the bag yet.</p>}
          {bag.length > 0 && (
            <ul className="bag__lines">
              {bag.map((l, i) => (
                <li key={l.id + '-' + l.glaze} className="bagline">
                  <span className="bagline__sw" style={{ background: glaze(l.glaze).accent }} aria-hidden="true" />
                  <span className="bagline__name">
                    {l.name}
                    <span className="bagline__glaze mono"> in {glazeName(l.glaze)}</span>
                  </span>
                  <span className="bagline__qty mono">
                    <button type="button" onClick={() => bump(i, -1)} aria-label={'One fewer ' + l.name + ' in ' + glazeName(l.glaze)}>&minus;</button>
                    <b>{l.qty}</b>
                    <button type="button" onClick={() => bump(i, 1)} aria-label={'One more ' + l.name + ' in ' + glazeName(l.glaze)}>+</button>
                  </span>
                  <span className="bagline__price mono">{l.qty} &times; £{l.price} = £{l.price * l.qty}</span>
                  <button type="button" className="bagline__rm" onClick={() => remove(i)} aria-label={'Remove ' + l.name + ' in ' + glazeName(l.glaze)}>Remove</button>
                </li>
              ))}
            </ul>
          )}
          <div className="bag__foot">
            <p className="bag__total"><span>Total</span><b className="mono">£{total}</b></p>
            <p className="mono bag__ship">
              {total >= 60
                ? 'Free shipping — this is over £60.'
                : '£5.50 shipping under £60' + (total > 0 ? '. £' + (60 - total) + ' to go.' : '.')}
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

/* =========================================================================
   Kilnwork
   ---------------------------------------------------------------------
   Colour is not chosen, it is sampled: every ground, rule and accent below
   comes from one of the three real glazes, and the whole route is repainted
   when the reader picks one. Fraunces is set with its optical-size and SOFT
   axes open because the display faces here are large and want to be a little
   irregular; IBM Plex Mono carries anything that is a measurement, because
   measurements are what the studio actually writes on a pot.
   ========================================================================= */

:root {
  --paper: #edebe2;
  --paper-deep: #dfded2;
  --ink: #1e211c;
  --accent: #5f7059;
  --rule: #bcbfaf;

  --dark: #14120f;
  --dark-2: #1e1a16;

  --sans: 'Fraunces', 'Iowan Old Style', Georgia, serif;
  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;

  --gap: clamp(20px, 3.2vw, 46px);
  --pad: clamp(20px, 5vw, 92px);
  --maxw: 1520px;

  --t: 160ms cubic-bezier(.32, .06, .2, 1);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-variation-settings: 'SOFT' 18, 'WONK' 0, 'opsz' 14;
  font-size: clamp(15.5px, 1.02vw, 17.5px);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

.route {
  background: var(--paper);
  transition: background-color 520ms ease, color 520ms ease;
  min-height: 100vh;
  color: var(--ink);
}

img { display: block; max-width: 100%; }

.sr {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.mono {
  font-family: var(--mono);
  font-size: .705rem;
  letter-spacing: .085em;
  text-transform: uppercase;
  font-weight: 450;
}

.wrap { max-width: var(--maxw); margin-inline: auto; padding-inline: var(--pad); }

.h2 {
  font-size: clamp(2.1rem, 4.4vw, 3.9rem);
  font-variation-settings: 'SOFT' 30, 'WONK' 1, 'opsz' 92;
  font-weight: 400;
  line-height: .98;
  letter-spacing: -.022em;
  margin: 0 0 .5em;
  text-wrap: balance;
}

.lede {
  font-size: clamp(1.06rem, 1.42vw, 1.34rem);
  line-height: 1.44;
  max-width: 46ch;
  margin: 0 0 1em;
  color: color-mix(in srgb, var(--ink) 88%, var(--paper));
}

p { margin: 0 0 1em; max-width: 62ch; }

a { color: inherit; }

:where(button, a, summary):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 1px;
}

/* --- regional entrance: the interaction floor, cheap and uniform --------- */
[data-enter] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 620ms cubic-bezier(.2, .5, .2, 1), transform 620ms cubic-bezier(.2, .5, .2, 1);
}
[data-enter].is-in { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  [data-enter] { opacity: 1; transform: none; transition: none; }
}

/* --- the glaze pour ------------------------------------------------------ */
.wash {
  position: fixed;
  inset: -80vh 0 auto 0;
  height: 80vh;
  z-index: 60;
  pointer-events: none;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    color-mix(in srgb, var(--to) 55%, transparent) 22%,
    var(--to) 52%,
    color-mix(in srgb, var(--to) 72%, transparent) 82%,
    transparent 100%
  );
  animation: pour 940ms cubic-bezier(.42, 0, .3, 1) forwards;
}
@keyframes pour {
  from { transform: translateY(0); }
  to { transform: translateY(190vh); }
}

/* =========================================================== masthead === */
.mast {
  position: sticky;
  top: 0;
  z-index: 50;
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: blur(9px) saturate(1.1);
  border-bottom: 1px solid var(--rule);
  transition: background-color 520ms ease, border-color 520ms ease;
}
.mast__in {
  max-width: var(--maxw);
  margin-inline: auto;
  padding: 11px var(--pad);
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: clamp(14px, 2.4vw, 40px);
}
.mast__logo {
  text-decoration: none;
  display: grid;
  line-height: 1;
  font-size: 1.28rem;
  font-variation-settings: 'SOFT' 34, 'WONK' 1, 'opsz' 60;
  letter-spacing: -.014em;
}
.mast__sub { opacity: .6; font-size: .58rem; margin-top: 5px; }
.mast__nav { display: flex; gap: clamp(12px, 1.7vw, 28px); }
.mast__nav a {
  text-decoration: none;
  opacity: .62;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
  transition: opacity var(--t), border-color var(--t);
}
.mast__nav a:hover { opacity: 1; border-bottom-color: var(--accent); }

.picker {
  display: flex;
  gap: 0;
  border: 1px solid var(--rule);
  border-radius: 999px;
  padding: 2px;
  margin: 0;
  background: color-mix(in srgb, var(--paper-deep) 60%, transparent);
}
.picker__b {
  font-family: var(--mono);
  font-size: .64rem;
  letter-spacing: .07em;
  text-transform: uppercase;
  background: none;
  border: 0;
  color: inherit;
  cursor: pointer;
  padding: 7px 13px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  opacity: .58;
  transition: opacity var(--t), background-color var(--t), transform var(--t);
}
.picker__b:hover { opacity: .92; }
.picker__b:active { transform: translateY(1px); }
.picker__b.is-on {
  opacity: 1;
  background: var(--paper);
  box-shadow: 0 1px 0 color-mix(in srgb, var(--ink) 14%, transparent);
}
.picker__dot {
  width: 11px; height: 11px; border-radius: 50%;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 25%, transparent);
}

.mast__bag {
  font-family: var(--mono);
  font-size: .66rem;
  letter-spacing: .09em;
  text-transform: uppercase;
  background: none;
  border: 1px solid var(--ink);
  color: var(--ink);
  padding: 9px 15px;
  cursor: pointer;
  display: inline-flex;
  gap: 9px;
  transition: background-color var(--t), color var(--t), transform var(--t);
}
.mast__bag:hover { background: var(--ink); color: var(--paper); }
.mast__bag:active { transform: translateY(1px); }
.mast__bag.has-items { background: var(--accent); border-color: var(--accent); color: var(--paper); }
.mast__bag.has-items:hover { background: var(--ink); border-color: var(--ink); }

/* =============================================================== hero === */
.hero {
  display: grid;
  grid-template-columns: 1.02fr .98fr;
  align-items: stretch;
  border-bottom: 1px solid var(--rule);
}
.hero__type {
  padding: clamp(48px, 7vw, 110px) clamp(28px, 4.4vw, 78px) clamp(44px, 6vw, 90px) var(--pad);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.hero__kicker { opacity: .58; margin-bottom: clamp(24px, 4vw, 48px); }
.hero__h1 {
  font-size: clamp(2.7rem, 6.1vw, 5.6rem);
  font-variation-settings: 'SOFT' 40, 'WONK' 1, 'opsz' 120;
  font-weight: 400;
  line-height: .95;
  letter-spacing: -.032em;
  margin: 0 0 .42em;
}
.hero__h1 em { font-style: italic; color: var(--accent); font-variation-settings: 'SOFT' 60, 'WONK' 1, 'opsz' 120; }
.hero__lede { font-size: clamp(1rem, 1.22vw, 1.2rem); max-width: 42ch; margin-bottom: 2em; opacity: .86; }
.hero__acts { display: flex; gap: 14px; flex-wrap: wrap; }

.btn {
  font-family: var(--mono);
  font-size: .68rem;
  letter-spacing: .1em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 14px 24px;
  background: var(--ink);
  color: var(--paper);
  border: 1px solid var(--ink);
  display: inline-block;
  transition: background-color var(--t), color var(--t), transform var(--t);
}
.btn:hover { background: var(--accent); border-color: var(--accent); }
.btn:active { transform: translateY(1px); }
.btn--quiet { background: none; color: var(--ink); }
.btn--quiet:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }

.hero__fig { margin: 0; position: relative; min-height: clamp(380px, 62vh, 760px); border-left: 1px solid var(--rule); }
.hero__fig img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 42%; }
.hero__fig figcaption {
  position: absolute; left: 0; bottom: 0; right: 0;
  padding: 14px 20px;
  color: #f2ede5;
  background: linear-gradient(to top, rgba(18, 15, 12, .72), transparent);
  font-size: .62rem;
}

/* ========================================================= difference === */
.diff {
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  gap: clamp(28px, 4vw, 76px);
  align-items: center;
  padding: clamp(64px, 9vw, 150px) var(--pad);
  max-width: var(--maxw);
  margin-inline: auto;
}
.diff__fig { margin: 0; position: relative; }
.diff__fig img { width: 100%; height: auto; }

.diff__note {
  position: absolute;
  display: flex;
  gap: 10px;
  align-items: flex-start;
  width: min(240px, 42%);
  font-size: .82rem;
  line-height: 1.34;
  color: var(--ink);
  background: color-mix(in srgb, var(--paper) 90%, transparent);
  backdrop-filter: blur(3px);
  padding: 9px 11px;
  border-left: 2px solid var(--accent);
}
.diff__note b {
  flex: none;
  width: 19px; height: 19px;
  display: grid; place-items: center;
  background: var(--accent);
  color: var(--paper);
  border-radius: 50%;
  font-size: .58rem;
  letter-spacing: 0;
}
.diff__note--a { top: 16%; left: 2%; }
.diff__note--b { top: 45%; right: 1%; }
.diff__note--c { bottom: 7%; left: 12%; }

.diff__body h2 { margin-bottom: .38em; }

/* ============================================================= glazes === */
.glazes {
  padding: clamp(56px, 8vw, 132px) 0;
  border-top: 1px solid var(--rule);
  background: linear-gradient(to bottom, var(--paper-deep), var(--paper) 62%);
}
.glazes__head { margin-bottom: clamp(28px, 3.6vw, 56px); }
.glazes__row {
  max-width: var(--maxw);
  margin-inline: auto;
  padding-inline: var(--pad);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--gap);
}
.glazec {
  appearance: none;
  border: 1px solid var(--rule);
  background: var(--paper);
  color: inherit;
  padding: 0;
  text-align: left;
  cursor: pointer;
  display: grid;
  grid-template-rows: auto 1fr;
  transition: border-color var(--t), transform var(--t), box-shadow var(--t);
}
.glazec:hover { transform: translateY(-3px); box-shadow: 0 10px 26px -18px color-mix(in srgb, var(--ink) 70%, transparent); }
.glazec:active { transform: translateY(-1px); }
.glazec.is-on { border-color: var(--accent); box-shadow: inset 0 0 0 1px var(--accent); }
.glazec__fig { display: block; overflow: hidden; aspect-ratio: 5 / 4; background: var(--paper-deep); }
.glazec__fig img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 700ms cubic-bezier(.2, .5, .2, 1), filter 520ms ease;
  filter: saturate(.9);
}
.glazec:hover .glazec__fig img { transform: scale(1.035); }
.glazec.is-on .glazec__fig img { filter: saturate(1.06) contrast(1.04); }
.glazec__meta { display: grid; gap: 8px; padding: 18px 20px 20px; align-content: start; }
.glazec__name {
  font-size: 1.5rem;
  font-variation-settings: 'SOFT' 30, 'WONK' 1, 'opsz' 60;
  line-height: 1;
}
.glazec__note { font-size: .95rem; opacity: .8; line-height: 1.4; }
.glazec__cta { margin-top: 6px; color: var(--accent); opacity: .75; font-size: .6rem; }
.glazec.is-on .glazec__cta { opacity: 1; }

.tiles {
  max-width: var(--maxw);
  margin: clamp(40px, 5.5vw, 90px) auto 0;
  padding-inline: var(--pad);
  display: grid;
  grid-template-columns: .8fr 1.15fr .8fr;
  gap: var(--gap);
  align-items: center;
}
.tiles__fig { margin: 0; }
.tiles__fig img { width: 100%; height: auto; }
.tiles__fig--b { transform: translateY(clamp(12px, 2vw, 34px)); }
.tiles__body { text-align: center; padding-inline: clamp(0px, 1.5vw, 26px); }
.tiles__big {
  font-size: clamp(1.5rem, 2.5vw, 2.35rem);
  font-variation-settings: 'SOFT' 34, 'WONK' 1, 'opsz' 72;
  line-height: 1.06;
  letter-spacing: -.018em;
  margin: 0 auto .8em;
  max-width: 20ch;
  text-wrap: balance;
}
.tiles__body p:last-child { font-size: .95rem; opacity: .82; margin-inline: auto; max-width: 44ch; }

/* ========================================================== true scale === */
.scale {
  --ppm: 1.18px;
  padding: clamp(56px, 8vw, 128px) 0 clamp(40px, 5vw, 72px);
  border-top: 1px solid var(--rule);
}
.scale__head { margin-bottom: clamp(26px, 3.6vw, 52px); }
.scale__rail {
  position: relative;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 0 var(--pad) 8px;
  scrollbar-width: thin;
}
.scale__floor {
  display: flex;
  align-items: flex-end;
  gap: calc(24 * var(--ppm));
  height: calc(280 * var(--ppm) + 62px);
  padding-bottom: 62px;
  width: max-content;
  border-bottom: 1px solid var(--ink);
}
.scale__piece {
  appearance: none;
  background: none;
  border: 0;
  padding: 0;
  color: inherit;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  position: relative;
  align-self: flex-end;
}
.scale__draw { display: block; }
.scale__body,
.scale__handle {
  fill: color-mix(in srgb, var(--ink) 13%, transparent);
  stroke: color-mix(in srgb, var(--ink) 62%, transparent);
  stroke-width: 2.4;
  vector-effect: non-scaling-stroke;
  transition: fill 200ms ease, stroke 200ms ease;
}
.scale__handle { fill: none; stroke-width: 7; stroke-linecap: round; }
.scale__piece:hover .scale__body,
.scale__piece:hover .scale__handle { fill: color-mix(in srgb, var(--accent) 26%, transparent); stroke: var(--accent); }
.scale__piece:hover .scale__handle { fill: none; }
.scale__piece.is-on .scale__body { fill: color-mix(in srgb, var(--accent) 62%, transparent); stroke: var(--accent); }
.scale__piece.is-on .scale__handle { fill: none; stroke: var(--accent); }

.scale__tag {
  position: absolute;
  top: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%);
  display: grid;
  justify-items: center;
  gap: 2px;
  white-space: nowrap;
}
.scale__name { font-size: .84rem; line-height: 1; }
.scale__mm { font-size: .58rem; opacity: .55; letter-spacing: .05em; }
.scale__unit { opacity: .6; margin-left: 2px; }
.scale__piece:hover .scale__name,
.scale__piece.is-on .scale__name { color: var(--accent); }

.scale__rule { position: relative; height: 26px; margin: 12px var(--pad) 0; width: max-content; }
.scale__tick { position: absolute; top: 0; width: 1px; height: 5px; background: color-mix(in srgb, var(--ink) 35%, transparent); }
.scale__tick.is-major { height: 10px; background: color-mix(in srgb, var(--ink) 60%, transparent); }
.scale__tick i {
  position: absolute; top: 12px; left: 0; transform: translateX(-50%);
  font-style: normal; font-size: .54rem; opacity: .5; letter-spacing: .06em;
}

/* =============================================================== shop === */
.shop { padding: clamp(56px, 8vw, 124px) 0 clamp(60px, 8vw, 130px); border-top: 1px solid var(--rule); }
.shop__head {
  display: flex; align-items: baseline; justify-content: space-between;
  gap: 20px; flex-wrap: wrap; margin-bottom: clamp(24px, 3.4vw, 48px);
}
.shop__head .h2 { margin-bottom: 0; }
.shop__state { opacity: .62; }
.shop__state b { color: var(--accent); font-weight: 450; }

.grid {
  max-width: var(--maxw);
  margin-inline: auto;
  padding-inline: var(--pad);
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: var(--gap);
  align-items: start;
}
.card {
  grid-column: span var(--span);
  display: grid;
  gap: 14px;
  transition: opacity 420ms ease;
}
.card__figure {
  position: relative;
  overflow: hidden;
  background: var(--paper-deep);
  border: 1px solid var(--rule);
}
.card__figure img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 800ms cubic-bezier(.2, .5, .2, 1), filter 480ms ease;
}
.card:hover .card__figure img { transform: scale(1.028); }
.card.is-selected { outline: 1px solid var(--accent); outline-offset: 9px; }
.card.is-elsewhere .card__figure img { filter: saturate(.42) contrast(.96); }
.card.is-out .card__figure img { filter: grayscale(.5) opacity(.72); }

.card__flag {
  position: absolute; top: 12px; left: 12px;
  background: var(--ink); color: var(--paper);
  padding: 5px 9px; font-size: .58rem;
}

.card__name {
  margin: 0;
  font-size: clamp(1.2rem, 1.5vw, 1.5rem);
  font-variation-settings: 'SOFT' 28, 'WONK' 0, 'opsz' 48;
  font-weight: 400;
  line-height: 1.05;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 14px;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 8px;
}
.card__price { font-size: .84rem; letter-spacing: .04em; opacity: .8; text-transform: none; }

.card__specs { margin: 0; display: grid; gap: 5px; font-size: .63rem; }
.card__specs > div { display: flex; gap: 10px; align-items: baseline; }
.card__specs dt { opacity: .45; min-width: 38px; }
.card__specs dd { margin: 0; opacity: .78; letter-spacing: .04em; }
.card__care { padding-top: 3px; }
.card__care dd { display: flex; gap: 8px; }

.mark { display: inline-flex; }
.mark svg { width: 19px; height: 19px; fill: none; stroke: var(--ink); stroke-width: 1.4; opacity: .62; }
.mark--no svg { opacity: .34; }
.mark--no .mark__bar { stroke: var(--accent); stroke-width: 1.7; opacity: 1; }

.card__outnote { font-size: .84rem; opacity: .68; line-height: 1.38; margin: 0; max-width: 34ch; }

.card__buy { display: grid; gap: 8px; margin-top: 2px; }
.card__buylabel { opacity: .45; font-size: .58rem; }
.card.is-elsewhere .card__buylabel { opacity: .72; color: var(--accent); }
.card__glazes { display: flex; gap: 7px; flex-wrap: wrap; }

.gbtn {
  font-family: var(--mono);
  font-size: .62rem;
  letter-spacing: .07em;
  text-transform: uppercase;
  background: none;
  border: 1px solid var(--rule);
  color: var(--ink);
  padding: 8px 12px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: border-color var(--t), background-color var(--t), color var(--t), transform var(--t);
}
.gbtn:hover:not(:disabled) { border-color: var(--ink); background: var(--ink); color: var(--paper); }
.gbtn:hover:not(:disabled) .gbtn__swatch { box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .5); }
.gbtn:active:not(:disabled) { transform: translateY(1px); }
.gbtn.is-current { border-color: var(--accent); }
.gbtn:disabled { opacity: .3; cursor: not-allowed; }
.gbtn__swatch {
  width: 10px; height: 10px; border-radius: 50%;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ink) 30%, transparent);
}

.grid__aside {
  grid-column: span 4;
  align-self: stretch;
  border-top: 2px solid var(--ink);
  padding-top: 16px;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}
.grid__asidebig {
  font-size: clamp(1.5rem, 2.4vw, 2.2rem);
  font-variation-settings: 'SOFT' 34, 'WONK' 1, 'opsz' 72;
  line-height: 1.04;
  letter-spacing: -.018em;
  margin-bottom: .5em;
}
.grid__aside p { max-width: 44ch; }
.grid__asidefoot { opacity: .5; margin-top: auto; }

/* =============================================================== band === */
.band { position: relative; height: clamp(220px, 34vh, 380px); overflow: hidden; background: #000; }
.band img { width: 100%; height: 100%; object-fit: cover; opacity: .95; }
.band__cap { position: absolute; right: var(--pad); bottom: 14px; color: #e8ddc9; opacity: .55; font-size: .56rem; }

/* ============================================================= firing === */
.firing { position: relative; height: 340vh; background: var(--dark); color: #f0e9dd; }
.firing__pin { position: sticky; top: 0; height: 100vh; overflow: hidden; }

.firing__stage { --glow: 0; --glow2: 0; --soak: 0; position: absolute; inset: 0; }
.firing__img {
  width: 100%; height: 100%; object-fit: cover;
  filter:
    brightness(calc(.46 + var(--glow) * .5))
    contrast(calc(1 + var(--glow2) * .35))
    saturate(calc(.72 + var(--glow) * 1.5))
    sepia(calc(var(--glow) * .55));
}
/* incandescence, from the middle of the load outwards */
.firing__heat {
  position: absolute; inset: 0;
  mix-blend-mode: screen;
  opacity: var(--glow);
  background:
    radial-gradient(58% 62% at 50% 56%, rgba(255, 168, 46, .95), rgba(214, 74, 12, .55) 46%, rgba(80, 14, 0, 0) 78%),
    radial-gradient(120% 90% at 50% 100%, rgba(255, 96, 10, .5), transparent 62%);
}
.firing__bloom {
  position: absolute; inset: 0;
  mix-blend-mode: screen;
  opacity: calc(var(--glow2) * .92);
  background: radial-gradient(46% 48% at 50% 54%, rgba(255, 246, 214, .9), rgba(255, 190, 90, .25) 52%, transparent 76%);
  filter: blur(clamp(10px, 2.4vw, 30px));
}
/* the four hour hold: the light stops climbing and just sits there */
.firing__soak {
  position: absolute; inset: 0;
  mix-blend-mode: overlay;
  opacity: calc(var(--soak) * .55);
  background: radial-gradient(70% 70% at 50% 55%, rgba(255, 255, 245, .8), transparent 70%);
}

.firing__ui {
  position: relative;
  height: 100%;
  max-width: var(--maxw);
  margin-inline: auto;
  padding: clamp(24px, 5vh, 64px) var(--pad);
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: clamp(14px, 3vh, 34px);
  background: linear-gradient(to right, rgba(12, 10, 8, .78), rgba(12, 10, 8, .18) 58%, rgba(12, 10, 8, .5));
}
.firing__head { max-width: 40ch; }
.firing__title { color: #f7f1e6; margin-bottom: .22em; }
.firing__lede { font-size: clamp(1rem, 1.2vw, 1.16rem); opacity: .74; max-width: 38ch; margin: 0; }

.firing__readout { align-self: center; max-width: 640px; width: 100%; }
.firing__nums { display: flex; align-items: baseline; gap: 18px; margin-bottom: 14px; }
.firing__temp {
  font-family: var(--mono);
  font-size: clamp(2.6rem, 6.4vw, 5.4rem);
  letter-spacing: -.03em;
  text-transform: none;
  line-height: .9;
  color: #ffdca6;
  font-variant-numeric: tabular-nums;
}
.firing__hour { font-size: .78rem; opacity: .6; font-variant-numeric: tabular-nums; }

.firing__track {
  position: relative;
  height: 3px;
  background: rgba(255, 240, 220, .16);
  overflow: hidden;
}
.firing__fill {
  position: absolute; inset: 0;
  transform-origin: left;
  transform: scaleX(var(--p, 0));
  background: linear-gradient(to right, #6b3a12, #ff9b2f 72%, #ffe7bd);
}
.firing__hold { position: absolute; top: -3px; bottom: -3px; left: 77.8%; width: 1px; background: rgba(255, 240, 220, .5); }
.firing__ticks { display: flex; justify-content: space-between; margin-top: 9px; opacity: .38; font-size: .54rem; }

.firing__stages { position: relative; min-height: clamp(140px, 20vh, 210px); }
.firing__stagecopy {
  position: absolute;
  inset: auto 0 0 0;
  max-width: 54ch;
  opacity: 0;
  transform: translateY(12px);
  transition: opacity 480ms ease, transform 480ms ease;
  pointer-events: none;
}
.firing__stagecopy.is-on { opacity: 1; transform: none; }
.firing__stagecopy .label { color: #ffcb84; opacity: .85; display: block; margin-bottom: 10px; }
.firing__stagecopy p {
  font-size: clamp(1.15rem, 2.05vw, 1.85rem);
  font-variation-settings: 'SOFT' 30, 'WONK' 0, 'opsz' 60;
  line-height: 1.24;
  margin: 0;
  max-width: 30ch;
}

/* reduced motion: the same content, as a still and a list */
.firing--still {
  height: auto;
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  gap: var(--gap);
  padding: clamp(48px, 7vw, 110px) var(--pad);
  align-items: center;
}
.firing__still img { width: 100%; height: auto; filter: brightness(.8) sepia(.25) saturate(1.3); }
.firing__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 26px; }
.firing__list .label { color: #ffcb84; display: block; margin-bottom: 8px; }
.firing__list p { font-size: 1.1rem; margin: 0; }
.firing__sched { opacity: .55; margin-top: 26px; }

/* ============================================================= studio === */
.studio {
  display: grid;
  grid-template-columns: .62fr .78fr 1.1fr;
  gap: var(--gap);
  align-items: center;
  padding: clamp(60px, 8vw, 140px) var(--pad);
  max-width: var(--maxw);
  margin-inline: auto;
}
.studio figure { margin: 0; }
.studio figcaption { margin-top: 9px; opacity: .5; font-size: .56rem; }
.studio__tall img { width: 100%; height: auto; }
.studio__wide img { width: 100%; height: auto; aspect-ratio: 14 / 9; object-fit: cover; }

/* ============================================================== notes === */
.notes { padding: clamp(52px, 7vw, 120px) 0; border-top: 1px solid var(--rule); background: var(--paper-deep); }
.notes__row { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--gap); margin-top: clamp(20px, 3vw, 40px); }
.note { margin: 0; border-top: 2px solid var(--ink); padding-top: 20px; }
.note blockquote { margin: 0 0 20px; }
.note blockquote p {
  font-size: clamp(1.16rem, 1.85vw, 1.62rem);
  font-variation-settings: 'SOFT' 26, 'WONK' 0, 'opsz' 60;
  line-height: 1.3;
  letter-spacing: -.012em;
  margin: 0;
  text-wrap: pretty;
}
.note figcaption { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; }
.note__name { font-size: .95rem; }
.note__bought {
  background: none; border: 0; padding: 0; cursor: pointer;
  color: var(--accent); font-size: .6rem;
  border-bottom: 1px solid color-mix(in srgb, var(--accent) 40%, transparent);
  transition: border-color var(--t), color var(--t);
  font-family: var(--mono); letter-spacing: .085em; text-transform: uppercase;
}
.note__bought:hover { border-bottom-color: var(--accent); color: var(--ink); }

/* ============================================================== terms === */
.terms { padding: clamp(52px, 7vw, 120px) 0; border-top: 1px solid var(--rule); }
.terms__in { display: grid; grid-template-columns: repeat(2, 1fr); gap: clamp(30px, 5vw, 90px); }
.terms .h2 { font-size: clamp(1.6rem, 2.6vw, 2.4rem); }
.terms__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 18px; counter-reset: t; }
.terms__list li {
  position: relative;
  padding-left: 30px;
  max-width: 52ch;
  border-top: 1px solid var(--rule);
  padding-top: 14px;
  counter-increment: t;
}
.terms__list li::before {
  content: counter(t, decimal-leading-zero);
  position: absolute; left: 0; top: 15px;
  font-family: var(--mono); font-size: .58rem; opacity: .4; letter-spacing: .06em;
}

/* ============================================================= footer === */
.foot { background: var(--dark); color: #ece4d6; padding: clamp(44px, 6vw, 92px) 0 clamp(32px, 4vw, 60px); }
.foot__in { display: grid; grid-template-columns: 1fr 1fr; gap: var(--gap); align-items: start; }
.foot__mark {
  font-size: clamp(2rem, 4.4vw, 3.6rem);
  font-variation-settings: 'SOFT' 40, 'WONK' 1, 'opsz' 96;
  line-height: .95; margin: 0 0 .3em;
}
.foot__brand p:last-child { opacity: .6; max-width: 46ch; font-size: .95rem; }
.foot__credits summary { cursor: pointer; opacity: .62; padding: 8px 0; transition: opacity var(--t); }
.foot__credits summary:hover { opacity: 1; }
.foot__credits ul { list-style: none; margin: 14px 0 0; padding: 0; display: grid; gap: 7px; }
.foot__credits li { font-size: .56rem; opacity: .55; letter-spacing: .04em; display: flex; gap: 8px; flex-wrap: wrap; }
.foot__slot { min-width: 108px; opacity: .6; }
.foot__credits a { color: #f2c88a; }

/* ================================================================ bag === */
.bag {
  position: fixed;
  right: clamp(14px, 2.2vw, 34px);
  bottom: clamp(14px, 2.2vw, 34px);
  z-index: 70;
  width: min(430px, calc(100vw - 28px));
  background: var(--paper);
  border: 1px solid var(--ink);
  box-shadow: 0 20px 50px -26px rgba(20, 16, 12, .7);
  display: grid;
}
.bag__handle {
  appearance: none; background: var(--ink); color: var(--paper);
  border: 0; cursor: pointer;
  padding: 13px 16px;
  display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px;
  text-align: left;
  transition: background-color var(--t);
}
.bag__handle:hover { background: var(--accent); }
.bag__handletitle { font-size: 1.02rem; line-height: 1; }
.bag__handlesum { opacity: .74; font-size: .6rem; }
.bag__chev {
  width: 9px; height: 9px;
  border-right: 1.5px solid currentColor; border-bottom: 1.5px solid currentColor;
  transform: rotate(-135deg); transition: transform var(--t);
}
.bag.is-open .bag__chev { transform: rotate(45deg); }

.bag__panel { padding: 14px 16px 16px; max-height: min(58vh, 480px); overflow-y: auto; }
.bag__empty { opacity: .55; font-size: .92rem; margin: 6px 0 10px; }
.bag__lines { list-style: none; margin: 0 0 12px; padding: 0; display: grid; gap: 10px; }
.bagline {
  display: grid;
  grid-template-columns: 12px 1fr auto;
  grid-template-areas: 'sw name qty' '. price rm';
  gap: 4px 10px;
  align-items: center;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 10px;
}
.bagline__sw { grid-area: sw; width: 10px; height: 10px; border-radius: 50%; box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .25); }
.bagline__name { grid-area: name; font-size: 1rem; line-height: 1.2; }
.bagline__glaze { opacity: .55; font-size: .58rem; }
.bagline__qty { grid-area: qty; display: inline-flex; align-items: center; gap: 8px; }
.bagline__qty button {
  appearance: none; background: none; border: 1px solid var(--rule);
  width: 24px; height: 24px; cursor: pointer; color: inherit; line-height: 1;
  transition: border-color var(--t), background-color var(--t), color var(--t);
}
.bagline__qty button:hover { border-color: var(--ink); background: var(--ink); color: var(--paper); }
.bagline__qty b { min-width: 14px; text-align: center; font-weight: 500; font-variant-numeric: tabular-nums; }
.bagline__price { grid-area: price; opacity: .6; font-size: .58rem; }
.bagline__rm {
  grid-area: rm; justify-self: end;
  background: none; border: 0; padding: 0; cursor: pointer;
  font-family: var(--mono); font-size: .55rem; letter-spacing: .09em; text-transform: uppercase;
  opacity: .45; color: inherit; border-bottom: 1px solid transparent;
  transition: opacity var(--t), border-color var(--t);
}
.bagline__rm:hover { opacity: 1; border-bottom-color: var(--accent); }

.bag__foot { border-top: 2px solid var(--ink); padding-top: 12px; }
.bag__total { display: flex; justify-content: space-between; align-items: baseline; margin: 0 0 6px; font-size: 1.05rem; }
.bag__total b { font-size: 1.3rem; letter-spacing: -.01em; text-transform: none; }
.bag__ship { opacity: .55; font-size: .56rem; margin: 0; }

/* ========================================================== 1080 down === */
@media (max-width: 1080px) {
  .diff { grid-template-columns: 1fr; }
  .diff__note { position: static; width: auto; margin-top: 10px; backdrop-filter: none; }
  .diff__fig { margin-bottom: 18px; }
  .tiles { grid-template-columns: 1fr 1fr; }
  .tiles__body { grid-column: 1 / -1; order: -1; text-align: left; }
  .tiles__body p:last-child { margin-inline: 0; }
  .tiles__big { margin-inline: 0; }
  .studio { grid-template-columns: 1fr 1fr; }
  .studio__wide { grid-column: 1 / -1; }
  .grid { grid-template-columns: repeat(4, 1fr); }
  .card { grid-column: span 2; }
  .grid__aside { grid-column: 1 / -1; }
  .mast__nav { display: none; }
}

/* =========================================================== 780 down === */
@media (max-width: 780px) {
  .hero { grid-template-columns: 1fr; }
  .hero__type { padding: clamp(32px, 8vw, 56px) var(--pad) clamp(30px, 7vw, 50px); order: 2; }
  .hero__fig { order: 1; min-height: 54vh; border-left: 0; border-bottom: 1px solid var(--rule); }
  .hero__h1 { font-size: clamp(2.5rem, 10.5vw, 3.4rem); }

  .mast__in { grid-template-columns: 1fr auto; gap: 10px 12px; padding: 9px var(--pad); }
  .picker { grid-column: 1 / -1; justify-content: space-between; }
  .picker__b { flex: 1; justify-content: center; padding: 8px 6px; font-size: .58rem; }
  .mast__bag { padding: 8px 12px; }

  .glazes__row { grid-template-columns: 1fr; }
  .glazec { grid-template-columns: 40% 1fr; grid-template-rows: auto; }
  .glazec__fig { aspect-ratio: 1 / 1; height: 100%; }
  .glazec__meta { padding: 14px 16px; }

  .tiles { grid-template-columns: 1fr 1fr; }
  .tiles__fig--b { transform: none; }

  .scale { --ppm: .78px; }
  .scale__floor { gap: calc(30 * var(--ppm)); }
  .scale__name { font-size: .68rem; }

  .shop__head { flex-direction: column; align-items: flex-start; gap: 8px; }
  .grid { grid-template-columns: 1fr; }
  .card, .grid__aside { grid-column: 1 / -1; }
  .card__figure { aspect-ratio: 4 / 3 !important; }

  .firing { height: 300vh; }
  .firing__ui { background: linear-gradient(to top, rgba(12, 10, 8, .88), rgba(12, 10, 8, .3) 62%, rgba(12, 10, 8, .55)); }
  .firing__stagecopy p { font-size: 1.12rem; }
  .firing--still { grid-template-columns: 1fr; }

  .studio { grid-template-columns: 1fr; }
  .notes__row, .terms__in, .foot__in { grid-template-columns: 1fr; }

  .bag { left: 0; right: 0; bottom: 0; width: 100%; border-left: 0; border-right: 0; border-bottom: 0; }
  .bag__panel { max-height: 52vh; }
}

@media (max-width: 400px) {
  .tiles { grid-template-columns: 1fr; }
  .tiles__fig--b { display: none; }
  .glazec { grid-template-columns: 1fr; }
  .glazec__fig { aspect-ratio: 16 / 9; }
}

