import { chromium } from 'playwright'
import fs from 'fs'

const URL = 'http://127.0.0.1:4173/'
const out = '.scratch/shots'
fs.mkdirSync(out, { recursive: true })

const wide = { width: 1440, height: 900 }
const phone = { width: 390, height: 844 }

const errs = []

async function page(browser, viewport) {
  const ctx = await browser.newContext({ viewport, deviceScaleFactor: 1 })
  const p = await ctx.newPage()
  p.on('console', (m) => { if (m.type() === 'error') errs.push(viewport.width + ' console: ' + m.text().slice(0, 200)) })
  p.on('pageerror', (e) => errs.push(viewport.width + ' pageerror: ' + e.message.slice(0, 200)))
  p.on('requestfailed', (r) => errs.push(viewport.width + ' failed: ' + r.url().slice(0, 140)))
  await p.goto(URL, { waitUntil: 'networkidle' })
  await p.evaluate(() => document.fonts.ready)
  // let every entrance resolve before capturing
  await p.evaluate(async () => {
    const h = document.body.scrollHeight
    for (let y = 0; y < h; y += 500) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 45)) }
    window.scrollTo(0, 0)
    await new Promise((r) => setTimeout(r, 700))
  })
  return { ctx, p }
}

const b = await chromium.launch()

// ---- desktop full page
{
  const { ctx, p } = await page(b, wide)
  await p.screenshot({ path: `${out}/d-full.png`, fullPage: true })
  // sectional captures, because the pinned firing chapter cannot be told the
  // truth by a full-page shot
  for (const [name, sel] of [['hero', '#top'], ['diff', '#difference'], ['glazes', '#glazes'], ['scale', '#scale'], ['shop', '#shop']]) {
    const el = await p.$(sel)
